@include('admin.includes.header')<div class="main-content"><div class="page-content"><div class="container-fluid"><div class="card"><div class="card-body"><div class="d-flex justify-content-between"><h4>Reviews</h4>@can('create-reviews')<a class="btn btn-primary" href="{{route('reviews.create')}}">Add review</a>@endcan</div><form class="row g-2 my-3"><div class="col-md-6"><input class="form-control" name="q" value="{{request('q')}}" placeholder="Search name"></div><div class="col-md-2"><select class="form-select" name="rating"><option value="">All ratings</option>@foreach(range(1,5) as $rating)<option value="{{$rating}}" @selected((string)$rating===request('rating'))>{{$rating}}</option>@endforeach</select></div><div class="col-md-2"><select class="form-select" name="status"><option value="">All statuses</option><option value="1" @selected(request('status')==='1')>Active</option><option value="0" @selected(request('status')==='0')>Inactive</option></select></div><div class="col-md-2"><button class="btn btn-outline-primary">Filter</button></div></form><table class="table"><thead><tr><th>Name</th><th>Position</th><th>Rating</th><th>Status</th><th>Actions</th></tr></thead><tbody>@foreach($reviews as $review)<tr><td>{{$review->name}}</td><td>{{$review->position}}</td><td>{{$review->rating}}/5</td><td>{{$review->is_active?'Active':'Inactive'}}</td><td>@can('edit-reviews')<a class="btn btn-sm btn-primary" href="{{route('reviews.edit',$review)}}">Edit</a>@endcan @can('delete-reviews')<form class="d-inline" method="post" action="{{route('reviews.destroy',$review)}}">@csrf @method('DELETE')<button class="btn btn-sm btn-danger">Delete</button></form>@endcan</td></tr>@endforeach</tbody></table>{{$reviews->links('admin.vendor.pagination.bootstrap-5')}}</div></div></div></div></div>@include('admin.includes.footer')
